CREATE VIEW bi.DimCompany AS
SELECT * FROM (VALUES
('00020',N'虛擬台灣公司','TWD'),
('00027',N'虛擬昆山公司','CNY'),
('00026',N'虛擬檳城公司','MYR'),
('00029',N'虛擬塗佈公司','TWD'),
('00121',N'虛擬印尼公司','IDR')) V(CompanyKey,CompanyName,LocalCurrency);
